const express = require('express');
const { Server } = require('@tus/server');
const { FileStore } = require('@tus/file-store');
const { jwtAuth } = require('../auth');

const router = express.Router();
const tusServer = new Server({
  path: '/uploads',
  datastore: new FileStore({ directory: './tmp/tus' })
});

router.head('/uploads/:uploadId', jwtAuth, async (req, res) => {
  const upload = await tusServer.datastore.getUpload(req.params.uploadId);
  if (!upload) return res.status(404).end();

  if (upload.metadata?.uploaderId !== req.user.id && !req.user.isAdmin) {
    return res.status(403).end();
  }

  res.setHeader('Upload-Offset', upload.offset);
  res.setHeader('Upload-Length', upload.size);
  res.setHeader('Upload-Metadata', JSON.stringify(upload.metadata));
  res.status(200).end();
});
